<?php
declare(strict_types=1);
namespace App\Services;
use App\Core\Database;
final class ImportService{
 public static function productsCsv(string $path,int $userId,string $fileName):array{
  $pdo=Database::connection();$s=$pdo->prepare("INSERT INTO import_jobs(user_id,file_name,entity_type,status) OUTPUT INSERTED.id VALUES(:u,:f,'products','running')");$s->execute(['u'=>$userId,'f'=>$fileName]);$job=(int)$s->fetchColumn();$ok=0;$err=0;$details=[];$h=fopen($path,'rb');if(!$h)throw new \RuntimeException('فایل قابل خواندن نیست.');$head=fgetcsv($h);$map=[];foreach((array)$head as $i=>$v)$map[trim((string)$v)]=$i;if(!isset($map['product_code'],$map['product_name'],$map['unit_code']))throw new \RuntimeException('ستون‌های product_code، product_name و unit_code الزامی هستند.');$n=0;while(($row=fgetcsv($h))!==false){$n++;try{$code=trim((string)($row[$map['product_code']]??''));$name=trim((string)($row[$map['product_name']]??''));$uc=trim((string)($row[$map['unit_code']]??''));if($code===''||$name===''||$uc==='')throw new \RuntimeException('اطلاعات ناقص است.');$s=$pdo->prepare('SELECT id FROM units WHERE code=:c');$s->execute(['c'=>$uc]);$unit=$s->fetchColumn();if($unit===false)throw new \RuntimeException('واحد یافت نشد.');$s=$pdo->prepare('SELECT id FROM products WHERE product_code=:c');$s->execute(['c'=>$code]);$id=$s->fetchColumn();if($id===false){$s=$pdo->prepare('INSERT INTO products(product_code,product_name,unit_id) VALUES(:c,:n,:u)');$s->execute(['c'=>$code,'n'=>$name,'u'=>$unit]);}else{$s=$pdo->prepare('UPDATE products SET product_name=:n,unit_id=:u,updated_at=SYSDATETIME() WHERE id=:id');$s->execute(['n'=>$name,'u'=>$unit,'id'=>$id]);}$ok++;}catch(\Throwable $e){$err++;$details[]='ردیف '.$n.': '.$e->getMessage();}}fclose($h);$s=$pdo->prepare("UPDATE import_jobs SET status=:st,total_rows=:t,success_rows=:ok,error_rows=:er,error_report=:r,finished_at=SYSDATETIME() WHERE id=:id");$s->execute(['st'=>$err?'completed_with_errors':'completed','t'=>$ok+$err,'ok'=>$ok,'er'=>$err,'r'=>implode(PHP_EOL,$details),'id'=>$job]);return ['total'=>$ok+$err,'success'=>$ok,'errors'=>$err,'details'=>$details];
 }
}